; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: colecovision (ColecoVision - cartridge (bare metal)), starts in turbo mode
; ============================================================

			OUTPUT "COL.COL"		; the cartridge ROM
			org #8000

; ============================================================
; Cartridge ROM header (the platform's ntc_plat_romhead)
; ============================================================
; ------------------------------------------------------------
; The ColecoVision cartridge header (the compiler puts this section at #8000):
;   #8000  #55, #AA = no title screen, no delay (#AA, #55 = the title screen and the
;          10 second wait, with the title text at #8024)
;   #8002  four RAM pointers the BIOS's sprite and controller routines use (0: not used)
;   #800A  the start address
;   #800C  the RST #08 ... #38 vectors, then the NMI vector at #8021
; ------------------------------------------------------------
			db #55, #AA
			dw 0					; sprite name table (BIOS sprite routines): not used
			dw 0					; sprite order table: not used
			dw 0					; work buffer: not used
			dw 0					; controller map: not used
			dw ntc_cv_start
			jp ntc_cv_ret			; #800C RST #08
			jp ntc_cv_ret			; #800F RST #10
			jp ntc_cv_ret			; #8012 RST #18
			jp ntc_cv_ret			; #8015 RST #20
			jp ntc_cv_ret			; #8018 RST #28
			jp ntc_cv_ret			; #801B RST #30
			jp ntc_cv_ret			; #801E RST #38 (INT - not connected)
			jp ntc_cv_nmi			; #8021 NMI (the BIOS jumps here; the VDP's is off)
ntc_cv_ret:
			ret
ntc_cv_nmi:
			retn
ntc_cv_start:
			di
			ld sp, #6400			; the stack at the top of the 1K of RAM
			in a, (#BF)				; the VDP: its control latch reset, its frame flag clear
			ld a, #80				; R#1: 16K, display off, frame interrupt (NMI) OFF
			out (#BF), a
			ld a, #81
			out (#BF), a
			ld hl, ntc_cv_end
			push hl					; End comes back here
			jp ntc_start
ntc_cv_end:
			di
			halt					; stopped

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld hl, ntc_rimg		; ROM: the RAM image (variables, code that runs from RAM) to RAM
			ld de, ntc_rimg_ram
			ld bc, ntc_rimg_end - ntc_rimg + 1	; (+ 1: never 0)
			ldir
			ld hl, ntc_rimg_rend		; and the variables with no value cleared
			ld de, ntc_rimg_rend + 1
			ld bc, ntc_rbss_end - ntc_rimg_rend + 1
			ld (hl), 0
			ldir
			ld (ntc_csp), sp
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; Main.bas 14: Coleco.Reg 1, &H80
			dw fn_coleco_reg, lit_1, lit_128

			; Main.bas 15: Coleco.Reg 0, 0
			dw fn_coleco_reg, lit_0, lit_0

			; Main.bas 16: Coleco.Reg 2, 6          ' name table   VRAM &H1800
			dw fn_coleco_reg, lit_2, lit_6

			; Main.bas 17: Coleco.Reg 3, &H80       ' colour table VRAM &H2000
			dw fn_coleco_reg, lit_3, lit_128

			; Main.bas 18: Coleco.Reg 4, 0          ' patterns     VRAM &H0000
			dw fn_coleco_reg, lit_4, lit_0

			; Main.bas 19: Coleco.Reg 5, &H36       ' sprites      VRAM &H1B00
			dw fn_coleco_reg, lit_5, lit_54

			; Main.bas 20: Coleco.Reg 6, 7          ' sprite patterns VRAM &H3800
			dw fn_coleco_reg, lit_6, lit_7

			; Main.bas 21: Coleco.Reg 7, &HF4       ' the backdrop: dark blue
			dw fn_coleco_reg, lit_7, lit_244

			; Main.bas 23: Coleco.Fill 0, 16384, 0
			dw fn_coleco_fill, lit_0, lit_16384, lit_0

			; Main.bas 24: Coleco.Gfx
			dw fn_coleco_gfx

			; Main.bas 25: Coleco.Fill &H1800, 768, 2          ' dots everywhere
			dw fn_coleco_fill, lit_6144, lit_768, lit_2

			; Main.bas 26: Coleco.Fill &H1800, 32, 1           ' the border: top row
			dw fn_coleco_fill, lit_6144, lit_32, lit_1

			; Main.bas 27: Coleco.Fill &H1800 + 736, 32, 1     ' bottom row
			dw fn_coleco_fill, lit_6880, lit_32, lit_1

			; Main.bas 28: For r = 1 To 22
			dw kw_ltov, 1, var_r
for1_t:

			; Main.bas 29: Coleco.VPoke &H1800 + r * 32, 1       ' left column
			dw kw_mulvl, var_r, 32, tmp1
			dw kw_addl, tmp1, 6144, tmp0
			dw fn_coleco_vpoke, tmp0, lit_1

			; Main.bas 30: Coleco.VPoke &H1800 + r * 32 + 31, 1  ' right column
			dw kw_mulvl, var_r, 32, tmp1
			dw kw_addl, tmp1, 6144, tmp0
			dw kw_addl, tmp0, 31, tmp0
			dw fn_coleco_vpoke, tmp0, lit_1

			; Main.bas 31: Next
			dw kw_next1l, var_r, 22, for1_t
for1_e:

			; Main.bas 33: x = 120
			dw kw_ltov, 120, var_x

			; Main.bas 34: y = 88
			dw kw_ltov, 88, var_y

			; Main.bas 35: Coleco.Sprite x, y
			dw fn_coleco_sprite, var_x, var_y

			; Main.bas 36: Coleco.Reg 1, &HC2                  ' display on, 16 x 16 sprites, NMI off
			dw fn_coleco_reg, lit_1, lit_194

			; Main.bas 38: Do
do2_t:

			; Main.bas 39: Coleco.Frame
			dw fn_coleco_frame

			; Main.bas 40: j = Coleco.Joy
			dw fn_coleco_joy, var_coleco_joy_joy
			dw kw_vtov, var_coleco_joy_joy, var_j

			; Main.bas 41: If (j And 1) <> 0 Then y = y - Speed
			dw kw_andvl, var_j, 1, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse, if3_1
			dw kw_addl, var_y, -2, var_y
if3_1:

			; Main.bas 42: If (j And 4) <> 0 Then y = y + Speed
			dw kw_andvl, var_j, 4, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse, if4_1
			dw kw_addl, var_y, 2, var_y
if4_1:

			; Main.bas 43: If (j And 8) <> 0 Then x = x - Speed
			dw kw_andvl, var_j, 8, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse, if5_1
			dw kw_addl, var_x, -2, var_x
if5_1:

			; Main.bas 44: If (j And 2) <> 0 Then x = x + Speed
			dw kw_andvl, var_j, 2, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse, if6_1
			dw kw_addl, var_x, 2, var_x
if6_1:

			; Main.bas 45: If x < MinX Then x = MinX
			dw kw_scpltvl, var_x, 8
			dw kw_goto_iffalse, if7_1
			dw kw_ltov, 8, var_x
if7_1:

			; Main.bas 46: If x > MaxX Then x = MaxX
			dw kw_scpgtvl, var_x, 232
			dw kw_goto_iffalse, if8_1
			dw kw_ltov, 232, var_x
if8_1:

			; Main.bas 47: If y < MinY Then y = MinY
			dw kw_scpltvl, var_y, 8
			dw kw_goto_iffalse, if9_1
			dw kw_ltov, 8, var_y
if9_1:

			; Main.bas 48: If y > MaxY Then y = MaxY
			dw kw_scpgtvl, var_y, 168
			dw kw_goto_iffalse, if10_1
			dw kw_ltov, 168, var_y
if10_1:

			; Main.bas 49: Coleco.Sprite x, y
			dw fn_coleco_sprite, var_x, var_y

			; Main.bas 50: Loop
			dw do2_t_go
do2_e:
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			ret

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_coleco_reg:		; sub reg (asm keyword), Coleco.cls line 12
            pop hl              ; address of r [13]
            ld c, (hl)		; Coleco.cls 14
            pop hl              ; address of v [15]
            ld a, (hl)		; Coleco.cls 16
            out (#BF), a		; Coleco.cls 17
            ld a, c		; Coleco.cls 18
            or #80		; Coleco.cls 19
            nop		; Coleco.cls 20
            nop		; Coleco.cls 21
            out (#BF), a		; Coleco.cls 22
			ret			; end of #asm

fn_coleco_vpoke:		; sub vpoke (asm keyword), Coleco.cls line 28
            pop hl              ; address of addr [29]
            ld e, (hl)		; Coleco.cls 30
            inc hl		; Coleco.cls 31
            ld d, (hl)		; Coleco.cls 32
            pop hl              ; address of v [33]
            ld c, (hl)		; Coleco.cls 34
            ld a, e		; Coleco.cls 35
            out (#BF), a		; Coleco.cls 36
            ld a, d		; Coleco.cls 37
            and #3F		; Coleco.cls 38
            or #40              ; write [39]
            nop		; Coleco.cls 40
            out (#BF), a		; Coleco.cls 41
            ld a, c		; Coleco.cls 42
            nop		; Coleco.cls 43
            nop		; Coleco.cls 44
            nop		; Coleco.cls 45
            nop		; Coleco.cls 46
            out (#BE), a		; Coleco.cls 47
			ret			; end of #asm

fn_coleco_fill:		; sub fill (asm keyword), Coleco.cls line 53
            pop hl              ; address of addr [54]
            ld e, (hl)		; Coleco.cls 55
            inc hl		; Coleco.cls 56
            ld d, (hl)		; Coleco.cls 57
            pop hl              ; address of count [58]
            ld c, (hl)		; Coleco.cls 59
            inc hl		; Coleco.cls 60
            ld b, (hl)		; Coleco.cls 61
            pop hl              ; address of v [62]
            ld a, (hl)		; Coleco.cls 63
            ex af, af'          ; the value in A'		; Coleco.cls 64
            ld a, e		; Coleco.cls 65
            out (#BF), a		; Coleco.cls 66
            ld a, d		; Coleco.cls 67
            and #3F		; Coleco.cls 68
            or #40		; Coleco.cls 69
            nop		; Coleco.cls 70
            out (#BF), a		; Coleco.cls 71
            nop		; Coleco.cls 72
            nop		; Coleco.cls 73
            nop		; Coleco.cls 74
            nop		; Coleco.cls 75
fn_coleco_fill_fl_loop:		; Coleco.cls 76
            ex af, af'		; Coleco.cls 77
            out (#BE), a		; Coleco.cls 78
            ex af, af'		; Coleco.cls 79
            dec bc		; Coleco.cls 80
            ld a, b		; Coleco.cls 81
            or c		; Coleco.cls 82
            jr nz, fn_coleco_fill_fl_loop		; Coleco.cls 83
			ret			; end of #asm

fn_coleco_frame:		; sub frame (asm keyword), Coleco.cls line 89
fn_coleco_frame_fr_wait:		; Coleco.cls 90
            in a, (#BF)		; Coleco.cls 91
            rlca		; Coleco.cls 92
            jr nc, fn_coleco_frame_fr_wait		; Coleco.cls 93
			ret			; end of #asm

fn_coleco_joy:		; function joy (asm keyword), Coleco.cls line 99
            out (#C0), a        ; joystick mode (#C0-#DF: the pad, #80-#9F: the keypad) [100]
            in a, (#FC)         ; controller 1: active low [101]
            cpl		; Coleco.cls 102
            and #4F		; Coleco.cls 103
            ld e, a		; Coleco.cls 104
            ld d, 0		; Coleco.cls 105
            pop hl              ; address of the result [106]
            ld (hl), e		; Coleco.cls 107
            inc hl		; Coleco.cls 108
            ld (hl), d		; Coleco.cls 109
			ret			; end of #asm

fn_coleco_sprite:		; sub sprite (asm keyword), Coleco.cls line 116
            pop hl              ; address of x [117]
            ld c, (hl)		; Coleco.cls 118
            pop hl              ; address of y [119]
            ld a, (hl)		; Coleco.cls 120
            dec a		; Coleco.cls 121
            ld b, a		; Coleco.cls 122
            xor a		; Coleco.cls 123
            out (#BF), a        ; VRAM #1B00 for writing [124]
            ld a, #1B | #40		; Coleco.cls 125
            nop		; Coleco.cls 126
            nop		; Coleco.cls 127
            nop		; Coleco.cls 128
            out (#BF), a		; Coleco.cls 129
            ld a, b		; Coleco.cls 130
            nop		; Coleco.cls 131
            nop		; Coleco.cls 132
            nop		; Coleco.cls 133
            nop		; Coleco.cls 134
            out (#BE), a        ; Y - 1 [135]
            ld a, c		; Coleco.cls 136
            nop		; Coleco.cls 137
            nop		; Coleco.cls 138
            nop		; Coleco.cls 139
            nop		; Coleco.cls 140
            out (#BE), a        ; X [141]
			ret			; end of #asm

fn_coleco_gfx:		; sub gfx (asm keyword), Coleco.cls line 149
            ld ix, fn_coleco_gfx_gx_list		; Coleco.cls 150
fn_coleco_gfx_gx_next:		; Coleco.cls 151
            ld l, (ix + 0)      ; the data [152]
            ld h, (ix + 1)		; Coleco.cls 153
            ld c, (ix + 2)      ; its length, 0 = the end of the list [154]
            ld b, (ix + 3)		; Coleco.cls 155
            ld a, b		; Coleco.cls 156
            or c		; Coleco.cls 157
            jp z, fn_coleco_gfx_gx_done		; Coleco.cls 158
            ld a, (ix + 4)      ; its VRAM address [159]
            out (#BF), a		; Coleco.cls 160
            ld a, (ix + 5)		; Coleco.cls 161
            or #40		; Coleco.cls 162
            nop		; Coleco.cls 163
            nop		; Coleco.cls 164
            nop		; Coleco.cls 165
            out (#BF), a		; Coleco.cls 166
            nop		; Coleco.cls 167
            nop		; Coleco.cls 168
            nop		; Coleco.cls 169
fn_coleco_gfx_gx_cp:		; Coleco.cls 170
            ld a, (hl)		; Coleco.cls 171
            out (#BE), a		; Coleco.cls 172
            inc hl		; Coleco.cls 173
            dec bc		; Coleco.cls 174
            ld a, b		; Coleco.cls 175
            or c		; Coleco.cls 176
            jr nz, fn_coleco_gfx_gx_cp		; Coleco.cls 177
            ld de, 6		; Coleco.cls 178
            add ix, de		; Coleco.cls 179
            jr fn_coleco_gfx_gx_next		; Coleco.cls 180
fn_coleco_gfx_gx_list:    ; @const    data, length, VRAM address [181]
            dw fn_coleco_gfx_gx_tiles, 24, #0000		; Coleco.cls 182
            dw fn_coleco_gfx_gx_colour, 32, #2000		; Coleco.cls 183
            dw fn_coleco_gfx_gx_ball, 32, #3800		; Coleco.cls 184
            dw fn_coleco_gfx_gx_sat, 8, #1B00		; Coleco.cls 185
            dw 0, 0, 0		; Coleco.cls 186
fn_coleco_gfx_gx_tiles:   ; @const [187]
            db #00, #00, #00, #00, #00, #00, #00, #00   ; 0 blank [188]
            db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF   ; 1 solid [189]
            db #00, #00, #00, #00, #08, #00, #00, #00   ; 2 dot [190]
fn_coleco_gfx_gx_colour:  ; @const [191]
            db #F4, #BF, #BF, #BF, #BF, #BF, #BF, #BF		; Coleco.cls 192
            db #BF, #BF, #BF, #BF, #BF, #BF, #BF, #BF		; Coleco.cls 193
            db #BF, #BF, #BF, #BF, #BF, #BF, #BF, #BF		; Coleco.cls 194
            db #BF, #BF, #BF, #BF, #BF, #BF, #BF, #BF		; Coleco.cls 195
fn_coleco_gfx_gx_ball:    ; @const    16 x 16, top left, bottom left, top right, bottom right quarters [196]
            db #07, #1F, #3F, #7F, #7F, #FF, #FF, #FF		; Coleco.cls 197
            db #FF, #FF, #FF, #7F, #7F, #3F, #1F, #07		; Coleco.cls 198
            db #E0, #F8, #FC, #FE, #FE, #FF, #FF, #FF		; Coleco.cls 199
            db #FF, #FF, #FF, #FE, #FE, #FC, #F8, #E0		; Coleco.cls 200
fn_coleco_gfx_gx_sat:     ; @const    sprite 0: Y - 1, X, pattern, colour; then Y = #D0: no more sprites [201]
            db 87, 120, 0, 9		; Coleco.cls 202
            db #D0, 0, 0, 0		; Coleco.cls 203
fn_coleco_gfx_gx_done:		; Coleco.cls 204
			ret			; end of #asm


; ============================================================
; numbers passed by address (read only)
lit_1:			dw 1
lit_128:			dw 128
lit_0:			dw 0
lit_2:			dw 2
lit_6:			dw 6
lit_3:			dw 3
lit_4:			dw 4
lit_5:			dw 5
lit_54:			dw 54
lit_7:			dw 7
lit_244:			dw 244
lit_16384:			dw 16384
lit_6144:			dw 6144
lit_768:			dw 768
lit_32:			dw 32
lit_6880:			dw 6880
lit_194:			dw 194

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			pop hl
			ret z
			ld sp, hl
			ret

;## ntc_for_jump
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			ret nc
			ld sp, hl
			ret
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			ret nc
			ld sp, hl
			ret
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le:
			or a
			jr nz, ntc_for_end
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			ret c
			ld sp, hl
			ret
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge:
			or a
			jr nz, ntc_for_end
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			ret c
			ld sp, hl
			ret
ntc_for_end:
			pop hl
			ret

;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc
			inc (hl)
ntc_n1l_nc:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvl ntc_mul
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop de
			jp ntc_mul

;## kw_andvl
;kw_andvl, <var>, <literal>, <destvar>
kw_andvl:
			pop hl
			pop de
			ld a, (hl)
			and e
			ld e, a
			inc hl
			ld a, (hl)
			and d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvl ntc_cmp
;kw_scpltvl, <var>, <literal>
kw_scpltvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_slt

;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sgt

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## ntc_plat_data
;## ntc_plat_exit ntc_plat_data
ntc_plat_exit:
			jp (ix)



; ============================================================
; RAM image: the variables and the code that runs from RAM, built for #6000,
; copied there by the start code. Then the variables with no value (cleared)
; ============================================================
ntc_rimg:
			DISP #6000
ntc_rimg_ram:
; Variables
; ============================================================

var_r:			dw 0
var_x:			dw 0
var_y:			dw 0
var_j:			dw 0
var_coleco_joy_joy:			dw 0
tmp0:			dw 0
tmp1:			dw 0

ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; row (0 based)
ntc_scols:		db 32			; columns
ntc_srows:		db 24			; rows

ntc_rimg_rend:
			ENT
ntc_rimg_end:
ntc_rbss_p	= ntc_rimg_rend
ntc_rbss_end	equ ntc_rbss_p

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_rbss_end		; (ROM: the arrays go after the RAM variables)
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
; ROM: the cartridge, padded to its size
			ASSERT ntc_end <= #FFFF, "the program does not fit in the cartridge ROM (#8000 - #FFFF)"
			ASSERT ntc_rbss_end <= #6400 - 128, "the variables do not fit in RAM (#6000 up to #6400, less 128 bytes of stack)"
			IF ntc_end <= #8000 + 8192
			ds #8000 + 8192 - $, #FF		; 8K
			ELSEIF ntc_end <= #8000 + 16384
			ds #8000 + 16384 - $, #FF		; 16K
			ELSEIF ntc_end <= #8000 + 24576
			ds #8000 + 24576 - $, #FF		; 24K
			ELSEIF ntc_end <= #8000 + 32768
			ds #8000 + 32768 - $, #FF		; 32K
			ENDIF